import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-10-28 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-10-28 :: Ceph Orchestration Meeting","date":"2019-10-28T00:00:00.000Z","updated":"2019-11-04T00:00:00.000Z","tags":["Ceph","Orchestration","Distributed Storage","Storage Cluster","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-28_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-10-28_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-10-28_-_-_Ceph_Orchestration_Meeting.md"};function s(a,t,n,p,h,_){return r(),o("div",null,[...t[0]||(t[0]=[i('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 及相关项目开发进度讨论</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Active, Mike, Joshua, Kiefer, Emma 等</p><p><strong>会议内容</strong>：</p><p><strong>1. SSH Orchestrator 与 Docker 集成</strong>：</p><ul><li>Active 正在开发 SSH Orchestrator，并已取得进展。</li><li>Mike 与 Joshua 合作，将 SSH Orchestrator 与 Docker 集成，旨在改进 SAP 守护进程方案。</li><li>讨论了使用 bootstrap 命令的可能性，以及如何适用于更多容器。</li></ul><p><strong>2. Ceph 集群文件系统问题</strong>：</p><ul><li>讨论了 Ceph 集群中 MDS 进程的分配问题，以确保其在多个文件系统之间均匀分配。</li><li>发现现有设置无法将 MDS 分配到特定文件系统的问题，并讨论了解决方案。</li></ul><p><strong>3. Rook 项目进度</strong>：</p><ul><li>Active 提到了 Rook 项目的一些开放 PR，并请求其他成员查看。</li><li>讨论了 Rook 项目中的问题，例如 Python 代码的异步缓存处理。</li><li>讨论了将验证逻辑移动到 orchestrator 接口的可能性。</li></ul><p><strong>4. Ceph 存储设备信息收集</strong>：</p><ul><li>讨论了如何从存储设备中收集信息，并将其存储在 Ceph 存储系统中。</li><li>讨论了将存储设备信息添加到配置映射中，并使用配置映射来存储设备信息。</li></ul><p><strong>5. 其他</strong>：</p><ul><li>讨论了 Ceph 工作组的一些其他问题，例如工作负载的监控和集成。</li><li>讨论了将一些 PR 放入 IRC 频道进行讨论。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Active 继续开发 SSH Orchestrator。</li><li>Mike 和 Joshua 继续推进 Docker 集成工作。</li><li>解决 Ceph 集群文件系统问题。</li><li>完善 Rook 项目的验证逻辑。</li><li>收集 Ceph 存储设备信息。</li><li>讨论其他 Ceph 工作组问题。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph 领域的英文关键词，例如 SSH Orchestrator、Docker、SAP 守护进程、MDS、Rook、配置映射等。</li></ul>',20)])])}const u=e(l,[["render",s]]);export{g as __pageData,u as default};
